package com.ferreteriahuaman.service;
import com.ferreteriahuaman.dto.CustomerModels.*;import com.ferreteriahuaman.dto.CatalogModels.*;import com.ferreteriahuaman.repository.*;import com.ferreteriahuaman.security.*;import com.ferreteriahuaman.security.AuthModels.Identity;import com.fasterxml.jackson.databind.ObjectMapper;import java.math.BigDecimal;import java.time.LocalDateTime;
import org.springframework.context.annotation.Profile;import org.springframework.stereotype.Service;
@Service @Profile("db") public class CustomerService {
 private final CustomerRepository repo;private final BusinessTransactions tx;private final PurchaseRepository audit;private final ObjectMapper mapper;
 public CustomerService(CustomerRepository repo,BusinessTransactions tx,PurchaseRepository audit,ObjectMapper mapper){this.repo=repo;this.tx=tx;this.audit=audit;this.mapper=mapper;}
 private AuthFailure bad(String text){return new AuthFailure(400,text);}
 public Page<Customer> list(String q,String state,int page,int size){if(q.length()>100||!state.matches("A|I|^$")||page<0||page>1000000||size<1||size>100)throw bad("Revisa los filtros y la paginación");return repo.list(q.strip(),state,page,size);}
 private Customer get(long id,boolean lock){return repo.get(id,lock).orElseThrow(()->new AuthFailure(404,"Cliente no encontrado"));}
 public Customer get(long id){return get(id,false);}
 public Customer lookup(String document){if(!document.matches("(?!0+$)([0-9]{8}|[0-9]{11})"))throw bad("Escribe un DNI de 8 dígitos o un RUC de 11 dígitos");return repo.lookup(document).orElseThrow(()->new AuthFailure(404,"No se encontró un cliente activo con ese documento"));}
 private void version(LocalDateTime expected,Customer c){if(expected==null)throw bad("Falta la versión del cliente");if(!expected.equals(c.version()))throw new AuthFailure(409,"El cliente cambió. Vuelve a cargarlo antes de guardar");}
 public void validate(Input i){String pattern=i.tipoDocumento().equals("DNI")?"(?!00000000)[0-9]{8}":"(?!00000000000)[0-9]{11}";if(!i.documento().matches(pattern))throw bad("El documento no corresponde al tipo seleccionado");if(i.nombre().strip().equalsIgnoreCase("CLIENTE VARIOS"))throw bad("CLIENTE VARIOS se utiliza en ventas sin identificar y no se registra como cliente");if(i.tipoDocumento().equals("RUC")&&(i.direccion()==null||i.direccion().strip().length()<5))throw bad("Un cliente con RUC requiere una dirección de al menos 5 caracteres");}
 private String json(Object value){if(value==null)return null;try{return mapper.writeValueAsString(value);}catch(com.fasterxml.jackson.core.JsonProcessingException e){throw new IllegalStateException("No se pudo registrar la auditoría");}}
 private Customer record(Identity a,String action,long id,Customer before){var after=get(id);audit.event(a.id(),action,"cliente",id,json(before),json(after),null);return after;}
 public Customer save(Identity a,String pc,Long id,Input i){return tx.write(a,pc,"CLI.GESTIONAR",()->{validate(i);Customer before=id==null?null:get(id,true);if(before!=null){version(i.version(),before);if((!before.documento().equals(i.documento())||!before.tipoDocumento().equals(i.tipoDocumento()))&&repo.history(id))throw new AuthFailure(409,"El cliente tiene operaciones. Su documento histórico se conserva");repo.update(id,i);return record(a,"CLI.EDITAR",id,before);}long saved=repo.create(i);return record(a,"CLI.CREAR",saved,null);});}
 public Customer state(Identity a,String pc,long id,StateInput i){return tx.write(a,pc,"CLI.GESTIONAR",()->{var before=get(id,true);version(i.version(),before);if(before.estado().equals(i.estado()))return before;if(i.estado().equals("I")&&new BigDecimal(before.saldoPendiente()).signum()>0)throw new AuthFailure(409,"El cliente tiene un saldo pendiente. Resuelve su crédito antes de desactivarlo");repo.state(id,i.estado());return record(a,"CLI.ESTADO",id,before);});}
 public Customer credit(Identity a,String pc,long id,Credit i){return tx.write(a,pc,"CLI.CREDITO",()->{var before=get(id,true);version(i.version(),before);if(!before.estado().equals("A"))throw bad("Activa al cliente antes de configurar su crédito");if(i.limite().compareTo(new BigDecimal(before.saldoPendiente()))<0)throw new AuthFailure(409,"El límite no puede ser menor que el saldo pendiente");repo.credit(id,i.limite());return record(a,"CLI.CREDITO",id,before);});}
}
